"""Offline, bounded-DOM research dashboard; no analytics or remote scripts."""
import html,json
from pathlib import Path

def dashboard(path,report,candidates):
    # Untrusted text never enters an HTML sink in the interactive table.
    fields=('candidate_id','name','city','country','class','decision','source_id','source_record_id','evidence_urls','reasons','source_observed_on','license','existing_organisation_matches','potential_duplicates','existing_record_change_proposal')
    data=[{k:c.get(k) for k in fields} for c in candidates]
    blob=json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    template='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>MotionX bulk acquisition review</title>
<style>body{font:16px system-ui;background:#111824;color:#eef;max-width:1400px;margin:auto;padding:1.5rem}a{color:#9cd9ff}input,select,button{font:inherit;padding:.65rem;background:#202c40;color:#fff;border:1px solid #9ab;border-radius:.3rem;max-width:100%}label{display:inline-grid;gap:.4rem;margin:.7rem}.scroll{overflow:auto}table{border-collapse:collapse;width:100%}td,th{border:1px solid #52657d;padding:.7rem;vertical-align:top;overflow-wrap:anywhere}pre{white-space:pre-wrap;overflow-wrap:anywhere}button:focus-visible,input:focus-visible,select:focus-visible,a:focus-visible{outline:3px solid #ffd1d2}p{line-height:1.6}</style>
<h1>MotionX bulk acquisition review</h1><p><strong>No publication approved.</strong> A: reviewed location evidence. B: directory-listed, operation and services uncorroborated. C: research only. Provider existence confidence is uncalibrated and cannot verify capabilities. Proposed source identities are provisional; company leads are not physical studio counts.</p>
<p>Review the exact source policy, duplicate reasons, licence obligations and proposed catalogue diff before authorising a merge. Failed fetches and missing listings never close or delete studios. This artifact contains public research only, with no personal contacts.</p>
<details><summary>Coverage, source permissions and validation summary</summary><pre>REPORT</pre></details>
<label>Find company, location or unresolved reason<input id="q" type="search"></label><label>Evidence class<select id="class"><option value="">All</option><option>B</option><option>C</option></select></label><label>Country / territory<select id="country"><option value="">All</option></select></label><label>Identity risks<select id="risk"><option value="">All</option><option value="duplicate">Possible duplicates</option><option value="existing">Existing organisation match</option></select></label><p id="count" role="status" aria-live="polite"></p><div class="scroll"><table><thead><tr><th>Company / location</th><th>Country / city</th><th>Class / decision</th><th>Evidence & date</th><th>Review reasons / identity risks</th></tr></thead><tbody id="rows"></tbody></table></div><button id="previous">Previous</button> <button id="next">Next</button>
<p>All observations and source IDs remain in candidates.jsonl / candidates.csv. Download the accompanying archive, manifest, source policy and licence notices together. Page size limits rendered rows, not acquisition scope.</p>
<script id="candidate-data" type="application/json">DATA</script><script>
'use strict';const candidates=JSON.parse(document.getElementById('candidate-data').textContent),$=id=>document.getElementById(id);let page=0;const size=100;
for(const value of [...new Set(candidates.map(r=>r.country||'Not supplied'))].sort())$('country').append(new Option(value,value));
function render(){const q=$('q').value.toLocaleLowerCase(),cls=$('class').value,country=$('country').value,risk=$('risk').value;
const rows=candidates.filter(r=>(!cls||r.class===cls)&&(!country||(r.country||'Not supplied')===country)&&(!q||JSON.stringify(r).toLocaleLowerCase().includes(q))&&(!risk||(risk==='duplicate'?r.potential_duplicates?.length:r.existing_organisation_matches?.length))).sort((a,b)=>(a.country||'').localeCompare(b.country||'')||a.name.localeCompare(b.name));
page=Math.min(page,Math.max(0,Math.ceil(rows.length/size)-1));$('count').textContent=`${rows.length} matching observations · ${page*size+1}–${Math.min(rows.length,(page+1)*size)} (grouped by country and company)`;$('rows').replaceChildren();
for(const r of rows.slice(page*size,(page+1)*size)){const tr=document.createElement('tr');const text=value=>{const td=document.createElement('td');td.textContent=value;tr.append(td);return td;};text(r.name+' ['+r.candidate_id+']');text((r.country||'Not supplied')+' / '+r.city);text(r.class+' / '+r.decision);const evidence=text(r.source_id+' / '+r.source_record_id+' · '+r.source_observed_on+' · '+r.license+' ');for(const url of r.evidence_urls||[]){try{const u=new URL(url);if(u.protocol!=='https:'||u.username||u.password)continue;const a=document.createElement('a');a.href=u.href;a.target='_blank';a.rel='noopener noreferrer';a.textContent='Source evidence';evidence.append(a);}catch{}}
text((r.reasons||[]).join('; ')+' '+(r.potential_duplicates?JSON.stringify(r.potential_duplicates):'')+' '+(r.existing_organisation_matches||[]).join(', ')+(r.existing_record_change_proposal?' Before / observed: '+JSON.stringify(r.existing_record_change_proposal):''));$('rows').append(tr);}
$('previous').disabled=page===0;$('next').disabled=(page+1)*size>=rows.length;}
for(const id of ['q','class','country','risk'])$(id).oninput=()=>{page=0;render();};$('previous').onclick=()=>{page--;render();};$('next').onclick=()=>{page++;render();};render();</script></html>'''
    Path(path).write_text(template.replace('REPORT',html.escape(json.dumps(report,ensure_ascii=False,indent=2))).replace('DATA</script>',blob+'</script>'),encoding='utf-8')
